function buildOfficialMetrics(bundle){const {attempts,clos,answers,questions}=bundle,answerMap=new Map(answers.map(a=>[`${a.attempt_id}|${a.question_id}`,a])),attemptMap=new Map(attempts.map(a=>[a.id,a]));const classMetric=freshMetric(clos),students=new Map();for(const a of attempts){const m=students.get(a.student_id)||freshMetric(clos);m.attempts++;m.examIds.add(a.exam_id);m.scoreSum+=Number(a.score||0);m.scoreCount++;students.set(a.student_id,m);classMetric.attempts++;classMetric.examIds.add(a.exam_id);classMetric.scoreSum+=Number(a.score||0);classMetric.scoreCount++}for(const q of questions){const a=attemptMap.get(q.attempt_id);if(!a||!q.clo_code)continue;const ans=answerMap.get(`${q.attempt_id}|${q.question_id}`),right=ans?.is_correct===true,sm=students.get(a.student_id);if(sm){sm.clos[q.clo_code]??={correct:0,total:0};sm.clos[q.clo_code].total++;if(right)sm.clos[q.clo_code].correct++}classMetric.clos[q.clo_code]??={correct:0,total:0};classMetric.clos[q.clo_code].total++;if(right)classMetric.clos[q.clo_code].correct++}const finishedStudents=new Map([...students].map(([id,m])=>[id,finishMetric(m,clos)])),classFinished=finishMetric(classMetric,clos),studentValues=[...finishedStudents.values()];classFinished.gpa=studentValues.length?studentValues.reduce((s,x)=>s+x.gpa,0)/studentValues.length:0;return {classMetric:classFinished,students:finishedStudents}}
async function loadSubjectStudentProfiles(){const {data:members,error}=await db.from('subject_members').select('user_id,role').eq('subject_id',subjectId());if(error)throw error;const ids=[...new Set((members||[]).filter(x=>x.role==='student').map(x=>x.user_id))];if(!ids.length)return [];const {data,error:pe}=await db.from('profiles').select('id,full_name,mssv,email').in('id',ids);if(pe)throw pe;return (data||[]).sort((a,b)=>(a.full_name||a.email||'').localeCompare(b.full_name||b.email||'','vi'))}
